args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?dir ?dirLabel ?b ?other ?otherLabel ?odir ?odirLabel ?ob WHERE {
  VALUES (?film ?other) {
    (dbr:Colierul_de_turcoaze dbr:Leo_and_Loree)
    (dbr:Leo_and_Loree dbr:Colierul_de_turcoaze)
  }
  ?film dbo:director ?dir .
  ?dir dbo:birthDate ?b .
  ?other dbo:director ?odir .
  ?odir dbo:birthDate ?ob .
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?dir rdfs:label ?dirLabel . FILTER(lang(?dirLabel) = 'en') }
  OPTIONAL { ?other rdfs:label ?otherLabel . FILTER(lang(?otherLabel) = 'en') }
  OPTIONAL { ?odir rdfs:label ?odirLabel . FILTER(lang(?odirLabel) = 'en') }
  FILTER (?b < ?ob)
}
LIMIT 10

